from pathlib import Path
import base64
r=Path(__file__).resolve().parent
font=base64.b64encode((r/'assets/quiet-meadow-pixel.woff2').read_bytes()).decode()
css='''@font-face{font-family:QuietMeadowPixel;src:url(data:font/woff2;base64,FONT) format('woff2');font-display:swap}*{box-sizing:border-box}body{margin:0;background:#090d17;color:#eee;font-family:QuietMeadowPixel,monospace;overflow:hidden}button{font:inherit;cursor:pointer}button[hidden],[hidden]{display:none!important}#battle{position:absolute;left:0;top:0;width:1536px;height:1024px;transform-origin:0 0;background:radial-gradient(ellipse at 64% 48%,#25203755,transparent 65%),#080c14}#battle-stage{position:relative;width:1536px;height:1024px}#battle h1,#battle h2{font-weight:400}.lab-heading{position:absolute;left:72px;top:38px}.lab-heading small,.lab-intro>span,.lab-aside>span{font-size:13px;color:var(--skill-muted);letter-spacing:2px}.lab-heading h1{font-size:38px;margin:12px 0 3px}.lab-heading p{font-size:17px;color:var(--skill-muted);margin:0}#lab-list{position:absolute;left:72px;top:175px;width:320px;height:745px;display:flex;flex-direction:column;gap:5px;overflow:auto;scrollbar-width:thin}#lab-list button{display:flex;align-items:center;gap:8px;min-height:36px;padding:3px 9px;background:var(--skill-row);color:var(--skill-text);border:1px solid var(--skill-border);text-align:left}#lab-list button[aria-pressed=true]{background:var(--skill-active);border-color:var(--skill-accent)}#lab-list canvas{width:29px;height:29px;image-rendering:pixelated}#lab-list span{font-size:16px;flex:1}#lab-list small{font-size:11px;color:var(--skill-muted);white-space:nowrap}.lab-intro{position:absolute;left:478px;top:196px;width:565px}.lab-intro h2{font-size:28px;margin:12px 0}.lab-intro p{font-size:18px;line-height:26px;color:var(--skill-muted);margin:0}.lab-aside{position:absolute;left:1128px;top:198px;width:325px}.lab-aside p{font-size:18px;line-height:27px;color:var(--skill-muted);margin:25px 0}.lab-aside small{font-size:15px;line-height:22px;color:var(--skill-muted)}#lab-themes{display:flex;gap:8px;margin-top:16px}#lab-themes button,#lab-actions button,#lab-pause button{background:var(--skill-row);border:1px solid var(--skill-border);color:var(--skill-text);padding:8px 14px;font-size:17px}#lab-themes button[aria-pressed=true]{border-color:var(--skill-accent);background:var(--skill-active)}#lab-actions{position:absolute;left:478px;top:811px;display:flex;gap:15px}#lab-actions button:disabled{opacity:.4}#lab-summary{position:absolute;left:478px;top:862px;width:610px;font-size:18px;color:var(--skill-accent);line-height:25px}.lab-footer{position:absolute;left:72px;bottom:28px;color:var(--skill-muted);font-size:14px}#lab-pause{position:absolute;left:460px;top:352px;width:616px;height:424px;background:#070b15ee;border:3px solid var(--skill-border);z-index:30;display:flex;align-items:center;justify-content:center;gap:30px;flex-direction:column}#lab-pause strong{font-weight:400;font-size:32px}button:focus-visible{outline:2px solid var(--skill-accent);outline-offset:2px}'''.replace('FONT',font)
css+='\n'+(r/'battle-skills.css').read_text()+'\n'+(r/'neru-battle.css').read_text()+'\n'+(r/'skill-games.css').read_text()
script='\n'.join((r/n).read_text() for n in ['shop-model.js','shop-item-art.js','skill-games-model.js','skill-games-art.js','skill-games-ui.js','skill-games-preview.js'])
html=(r/'skill-games-preview-shell.html').read_text().replace('/* INLINE_STYLES */',css).replace('<!-- INLINE_SCRIPTS -->','<script>'+script+'</script><script type="text/plain" id="font-license">'+(r/'assets/FONT_LICENSE.txt').read_text()+'</script>')
(r/'skill-games-preview.html').write_text(html)
print('Skill practice preview:',len(html),'characters')
